    referenceAnswer: "\u6982\u8ff0\u6240\u5b66\u4e13\u4e1a\u6838\u5fc3\u8bfe\u7a0b\uff08\u673a\u8f66\u6784\u9020\u3001\u5236\u52a8\u673a\u3001\u884c\u8f66\u89c4\u7ae0\u3001\u5217\u8f66\u7f51\u7edc\u63a7\u5236\u7b49\uff09\uff0c\u8bf4\u660e\u54ea\u4e9b\u77e5\u8bc6\u76f4\u63a5\u7528\u4e8e\u673a\u8f66\u8fd0\u7528\u2014\u2014\u5982\u5236\u52a8\u539f\u7406\u7528\u4e8e\u51c6\u786e\u5224\u65ad\u5236\u52a8\u8ddd\u79bb\u3001\u4fe1\u53f7\u77e5\u8bc6\u7528\u4e8e\u786e\u8ba4\u884c\u8f66\u51ed\u8bc1\u3001\u5e94\u6025\u5904\u7406\u77e5\u8bc6\u7528\u4e8e\u975e\u6b63\u5e38\u884c\u8f66\u3002\u7a81\u51fa\u7406\u8bba\u4e0e\u5b9e\u8df5\u7ed3\u5408\uff0c\u57f9\u8bad\u671f\u95f4\u505a\u5230\u6807\u51c6\u5316\u4f5c\u4e1a\u3002",
    keyPoints: ["\u6982\u8ff0\u6240\u5b66\u4e13\u4e1a\u6838\u5fc3\u8bfe\u7a0b\uff08\u673a\u8f66\u6784\u9020\u3001\u5236\u52a8\u673a\u3001\u884c\u8f66\u89c4\u7ae0\u3001\u5217\u8f66\u7f51\u7edc\u63a7\u5236\u7b49\uff09", "\uff0c\u8bf4\u660e\u54ea\u4e9b\u77e5\u8bc6\u76f4\u63a5\u7528\u4e8e\u673a\u8f66\u8fd0\u7528\u2014\u2014\u5982\u5236\u52a8\u539f\u7406\u7528\u4e8e\u51c6\u786e\u5224\u65ad\u5236\u52a8\u8ddd\u79bb\u3001\u4fe1\u53f7\u77e5\u8bc6\u7528\u4e8e\u786e\u8ba4\u884c\u8f66\u51ed\u8bc1\u3001\u5e94\u6025\u5904\u7406\u77e5\u8bc6\u7528\u4e8e\u975e\u6b63\u5e38\u884c\u8f66\u3002", "\u7a81\u51fa\u7406\u8bba\u4e0e\u5b9e\u8df5\u7ed3\u5408\uff0c\u57f9\u8bad\u671f\u95f4\u505a\u5230\u6807\u51c6\u5316\u4f5c\u4e1a\u3002"],
    subCategory: "3.4 \u673a\u8f66\u53f8\u673a\u5c97\u4f4d\u7efc\u5408\u9898",
